265	// directly and the same text written with equivalent JSON escapes name the
266	// same dataset and produce the same report.
267	func TestUnmarshalPlanEquivalentEscapesSameDataset(t *testing.T) {
268		graphData := `{"datasets":[{"name":"数据集","upstreams":[]},{"name":"源�","upstreams":[]}]}`
269		graph, err := UnmarshalGraphFile([]byte(graphData))
270		if err != nil {
271			t.Fatalf("UnmarshalGraphFile: %v", err)
272		}
273	
274		direct := `{"changes":[{"name":"数据集","upstreams":["源�"]}],"removals":["旧�"]}`
275		escaped := `{"changes":[{"name":"\u6570\u636e\u96c6","upstreams":["\u6e90\ufffd"]}],"removals":["\u65e7\ufffd"]}`
276		if direct == escaped {
277			t.Fatal("test premise broken: the two spellings must differ as text")
278		}
279	
280		planDirect, err := UnmarshalPlan([]byte(direct))
281		if err != nil {
282			t.Fatalf("direct spelling rejected: %v", err)
283		}
284		planEscaped, err := UnmarshalPlan([]byte(escaped))
285		if err != nil {
286			t.Fatalf("escaped spelling rejected: %v", err)
287		}
288		if !reflect.DeepEqual(planDirect, planEscaped) {
289			t.Fatalf("equivalent spellings decoded differently:\n%+v\n%+v", planDirect, planEscaped)
290		}
291	
292		reportDirect, err := PreviewBatch(graph, planDirect)
293		if err != nil {
294			t.Fatalf("PreviewBatch direct: %v", err)
295		}
296		reportEscaped, err := PreviewBatch(graph, planEscaped)
297		if err != nil {
298			t.Fatalf("PreviewBatch escaped: %v", err)
299		}
300		jDirect, _ := json.Marshal(reportDirect)
301		jEscaped, _ := json.Marshal(reportEscaped)
302		if string(jDirect) != string(jEscaped) {
303			t.Fatalf("reports differ between spellings:\n%s\n%s", jDirect, jEscaped)
304		}
305		if len(reportDirect.ChangedDatasets) != 1 || reportDirect.ChangedDatasets[0] != "数据集" {
306			t.Fatalf("expected 数据集 to be the changed dataset, got %v", reportDirect.ChangedDatasets)
307		}
308	}
309	
310	// TestUnmarshalPlanCorruptNameNeverTouchesGraph: a plan rejected for a
311	// corrupt name leaves the graph it would have been applied to completely
312	// unchanged — including when the corrupt name could have deleted a real
313	// dataset after the decoder's silent rewrite.
314	func TestUnmarshalPlanCorruptNameNeverTouchesGraph(t *testing.T) {
315		graphData := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"down","upstreams":["源�"]}]}`
316		graph, err := UnmarshalGraphFile([]byte(graphData))
317		if err != nil {
318			t.Fatalf("UnmarshalGraphFile: %v", err)
319		}
320		before := snapshotGraph(graph)
321	
322		// "源" plus one broken byte decodes to the real dataset "源�": accepting
323		// it would delete a dataset the user never named.
324		if _, err := UnmarshalPlan([]byte(`{"removals":["源` + "\xff" + `"]}`)); err == nil {
325			t.Fatal("corrupt removal name must be rejected")
326		}
327		if after := snapshotGraph(graph); !reflect.DeepEqual(after, before) {
328			t.Fatalf("graph changed while reading a rejected plan:\nbefore %#v\nafter  %#v", before, after)
329		}
330	}
